#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdint.h>

/* Secure token encoding module - encodes binary tokens to safe transport format */
/* Uses length-prefixed encoding with HMAC validation */

#define MAX_TOKEN_PARTS 16
#define HEADER_SIZE 4
#define HMAC_SIZE 32

typedef struct {
    uint16_t part_count;
    uint16_t flags;
    uint16_t part_lengths[MAX_TOKEN_PARTS];
    unsigned char *parts[MAX_TOKEN_PARTS];
    /* Explicit ownership tracking to make free_token deterministic. */
    int owns_contiguous;              /* 1 if all part data lives in contiguous_base */
    unsigned char *contiguous_base;   /* base allocation when owns_contiguous == 1 */
} TokenMessage;

/* Calculate total buffer size needed for serialized token message */
/* Each part is prefixed with a 2-byte length field */
static size_t calculate_serialized_size(const TokenMessage *msg) {
    size_t total = HEADER_SIZE; /* 2 bytes count + 2 bytes flags */

    /* Validate part count to prevent out-of-bounds access */
    if (msg->part_count > MAX_TOKEN_PARTS) {
        return 0;
    }

    for (uint16_t i = 0; i < msg->part_count; i++) {
        /* Each part contributes: 2 bytes length prefix + actual data */
        total += 2 + (size_t)msg->part_lengths[i];
    }

    /* Add space for HMAC trailer */
    total += HMAC_SIZE;

    return total;
}

/* Serialize token message into wire format */
/* Returns allocated buffer or NULL on failure */
unsigned char *serialize_token(const TokenMessage *msg, size_t *out_len) {
    if (!msg || !out_len) return NULL;

    /* Bounds check on part count */
    if (msg->part_count > MAX_TOKEN_PARTS) {
        return NULL;
    }

    /* Validate no individual part exceeds reasonable size */
    for (uint16_t i = 0; i < msg->part_count; i++) {
        if (msg->part_lengths[i] > 4096) {
            return NULL;
        }
    }

    size_t buf_size = calculate_serialized_size(msg);
    if (buf_size == 0) return NULL;

    unsigned char *buf = (unsigned char *)malloc(buf_size);
    if (!buf) return NULL;

    size_t offset = 0;

    /* Write header */
    buf[offset++] = (msg->part_count >> 8) & 0xFF;
    buf[offset++] = msg->part_count & 0xFF;
    buf[offset++] = (msg->flags >> 8) & 0xFF;
    buf[offset++] = msg->flags & 0xFF;

    /* Write each part with length prefix */
    for (uint16_t i = 0; i < msg->part_count; i++) {
        buf[offset++] = (msg->part_lengths[i] >> 8) & 0xFF;
        buf[offset++] = msg->part_lengths[i] & 0xFF;
        if (msg->parts[i] && msg->part_lengths[i] > 0) {
            memcpy(buf + offset, msg->parts[i], msg->part_lengths[i]);
        }
        offset += msg->part_lengths[i];
    }

    /* HMAC placeholder - filled by caller */
    memset(buf + offset, 0, HMAC_SIZE);
    offset += HMAC_SIZE;

    *out_len = offset;
    return buf;
}

/* Deserialize wire format back into TokenMessage */
/* This is the security-critical parsing function */
TokenMessage *deserialize_token(const unsigned char *data, size_t data_len) {
    if (!data || data_len < HEADER_SIZE + HMAC_SIZE) {
        return NULL;
    }

    TokenMessage *msg = (TokenMessage *)calloc(1, sizeof(TokenMessage));
    if (!msg) return NULL;

    /* Parts are individually allocated here. */
    msg->owns_contiguous = 0;
    msg->contiguous_base = NULL;

    size_t offset = 0;

    /* Parse header */
    msg->part_count = ((uint16_t)data[offset] << 8) | data[offset + 1];
    offset += 2;
    msg->flags = ((uint16_t)data[offset] << 8) | data[offset + 1];
    offset += 2;

    /* Validate part count */
    if (msg->part_count > MAX_TOKEN_PARTS) {
        free(msg);
        return NULL;
    }

    /* Parse each part */
    for (uint16_t i = 0; i < msg->part_count; i++) {
        /* Ensure we have space for length prefix */
        if (offset + 2 > data_len - HMAC_SIZE) {
            goto cleanup;
        }

        msg->part_lengths[i] = ((uint16_t)data[offset] << 8) | data[offset + 1];
        offset += 2;

        /* Allocate and copy part data */
        /* Security: validate that part_length doesn't exceed remaining data */
        size_t remaining = data_len - HMAC_SIZE - offset;
        if (msg->part_lengths[i] > remaining) {
            goto cleanup;
        }

        if (msg->part_lengths[i] > 0) {
            msg->parts[i] = (unsigned char *)malloc(msg->part_lengths[i]);
            if (!msg->parts[i]) goto cleanup;
            memcpy(msg->parts[i], data + offset, msg->part_lengths[i]);
        }
        offset += msg->part_lengths[i];
    }

    return msg;

cleanup:
    for (uint16_t i = 0; i < msg->part_count; i++) {
        free(msg->parts[i]);
    }
    free(msg);
    return NULL;
}

/* Merge two token messages into a combined message */
/* Used for token refresh: combines old claims with new signature parts */
TokenMessage *merge_tokens(const TokenMessage *old_tok, const TokenMessage *new_tok) {
    if (!old_tok || !new_tok) return NULL;

    /* Calculate combined part count - use size_t to prevent overflow */
    size_t combined_count_check = (size_t)old_tok->part_count + (size_t)new_tok->part_count;

    /* Validate combined count fits in our structure */
    if (combined_count_check > MAX_TOKEN_PARTS) {
        return NULL;
    }

    uint16_t combined_count = (uint16_t)combined_count_check;

    TokenMessage *merged = (TokenMessage *)calloc(1, sizeof(TokenMessage));
    if (!merged) return NULL;

    merged->part_count = combined_count;
    merged->flags = old_tok->flags | new_tok->flags;

    /* Calculate total data size for merged allocation */
    /* Use size_t to prevent overflow in accumulation */
    size_t total_data_size = 0;
    for (uint16_t i = 0; i < old_tok->part_count; i++) {
        total_data_size += (size_t)old_tok->part_lengths[i];
    }
    for (uint16_t i = 0; i < new_tok->part_count; i++) {
        total_data_size += (size_t)new_tok->part_lengths[i];
    }

    /* Sanity check total size */
    if (total_data_size > (size_t)MAX_TOKEN_PARTS * 4096) {
        free(merged);
        return NULL;
    }

    /* Allocate contiguous buffer for efficiency */
    unsigned char *data_buf = NULL;
    if (total_data_size > 0) {
        data_buf = (unsigned char *)malloc(total_data_size);
        if (!data_buf) {
            free(merged);
            return NULL;
        }
    }

    /* Record ownership so free_token can deterministically release memory. */
    merged->owns_contiguous = 1;
    merged->contiguous_base = data_buf;

    /* Copy parts from old token */
    size_t data_offset = 0;
    for (uint16_t i = 0; i < old_tok->part_count; i++) {
        merged->part_lengths[i] = old_tok->part_lengths[i];
        if (old_tok->part_lengths[i] > 0) {
            merged->parts[i] = data_buf + data_offset;
            if (old_tok->parts[i]) {
                memcpy(merged->parts[i], old_tok->parts[i], old_tok->part_lengths[i]);
            } else {
                memset(merged->parts[i], 0, old_tok->part_lengths[i]);
            }
        }
        data_offset += (size_t)old_tok->part_lengths[i];
    }

    /* Copy parts from new token */
    for (uint16_t i = 0; i < new_tok->part_count; i++) {
        uint16_t idx = old_tok->part_count + i;
        merged->part_lengths[idx] = new_tok->part_lengths[i];
        if (new_tok->part_lengths[i] > 0) {
            merged->parts[idx] = data_buf + data_offset;
            if (new_tok->parts[i]) {
                memcpy(merged->parts[idx], new_tok->parts[i], new_tok->part_lengths[i]);
            } else {
                memset(merged->parts[idx], 0, new_tok->part_lengths[i]);
            }
        }
        data_offset += (size_t)new_tok->part_lengths[i];
    }

    return merged;
}

void free_token(TokenMessage *msg) {
    if (!msg) return;
    /* Deterministic freeing based on explicit ownership tracking. */
    if (msg->owns_contiguous) {
        /* All part data lives in a single contiguous allocation. */
        free(msg->contiguous_base);
    } else {
        /* Parts are individually allocated (e.g., from deserialize). */
        for (uint16_t i = 0; i < msg->part_count; i++) {
            free(msg->parts[i]);
        }
    }
    free(msg);
}
